"""Live ledger status for claims: is each settled claim's receipt in the ledger?

Uses the period `list` call (covered by the vendor's flat monthly fee) rather
than per-entry `show` (billed per call, kept with the finance desk since EXP-412).
Nothing is cached, so every screen reflects the ledger as it is right now.
"""
from hbexpense.models import POSTED
from hbexpense.util.dates import month_bounds, month_of

BOOKED = "booked"
NOT_BOOKED = "not_booked"


class LedgerStatusService:
    def __init__(self, ledger):
        self.ledger = ledger

    def for_claims(self, claims):
        """Map claim_id -> "booked" / "not_booked" / None (not settled yet)."""
        settled = [c for c in claims if c.status == POSTED and c.receipt]
        receipts_by_month = {}
        for month in sorted({month_of(c.spent_on) for c in settled}):
            date_from, date_to = month_bounds(month)
            receipts_by_month[month] = {r.receipt for r in self.ledger.list_rows(date_from, date_to)}
        status = {}
        for claim in claims:
            if claim.claim_id not in {c.claim_id for c in settled}:
                status[claim.claim_id] = None
                continue
            booked = claim.receipt in receipts_by_month[month_of(claim.spent_on)]
            status[claim.claim_id] = BOOKED if booked else NOT_BOOKED
        return status

